<template><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><div><h4 class="mb-1">Prescription management</h4><div class="text-muted small">Upload and review prescriptions for restricted medicines.</div></div><button class="btn btn-primary" @click="show=!show">Upload prescription</button></div>
<div v-if="show" class="card mb-3"><form class="card-body row g-3" @submit.prevent="create"><div class="col-md-4"><label class="form-label">Customer ID (optional)</label><input v-model="form.customer_id" type="number" class="form-control"></div><div class="col-md-4"><label class="form-label">Doctor name *</label><input v-model="form.doctor_name" class="form-control" required></div><div class="col-md-4"><label class="form-label">Doctor license</label><input v-model="form.doctor_license" class="form-control"></div><div class="col-md-4"><label class="form-label">Prescription date *</label><input v-model="form.prescription_date" type="date" class="form-control" required></div><div class="col-md-4"><label class="form-label">Prescription image / PDF</label><input type="file" class="form-control" accept=".jpg,.jpeg,.png,.pdf" @change="form.file=$event.target.files[0]"></div><div class="col-md-4"><label class="form-label">Notes</label><input v-model="form.notes" class="form-control"></div><div class="col-md-5"><label class="form-label">Prescribed medicine</label><select v-model.number="form.medicine_id" class="form-select"><option value="">Select medicine</option><option v-for="m in medicines" :key="m.id" :value="m.id">{{m.name}} {{m.strength}}</option></select></div><div class="col-md-2"><label class="form-label">Quantity (individual units)</label><input v-model.number="form.quantity" type="number" min="1" class="form-control"></div><div class="col-md-5"><label class="form-label">Dosage / instructions</label><input v-model="form.instructions" class="form-control" placeholder="e.g. 1 tablet twice daily"></div><div class="col-12 text-end"><button type="button" class="btn btn-light me-2" @click="show=false">Cancel</button><button class="btn btn-primary">Upload for review</button></div></form></div>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Prescription</th><th>Customer</th><th>Doctor</th><th>Date</th><th>Status</th><th class="text-end">Action</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td><b>{{p.prescription_no}}</b></td><td>{{p.customer?.name||'—'}}</td><td>{{p.doctor_name}} <button v-if="p.file_path" class="btn btn-link btn-sm p-0 ms-1" @click="openFile(p)">View file</button></td><td>{{p.prescription_date}}</td><td><span class="badge" :class="p.status==='approved'?'bg-success':p.status==='rejected'?'bg-danger':'bg-secondary'">{{p.status}}</span></td><td class="text-end"><button v-if="['admin','branch_manager','pharmacist'].includes(auth.user?.role) && p.status==='pending'" class="btn btn-sm btn-primary me-1" @click="review(p,'approve')">Approve</button><button v-if="['admin','branch_manager','pharmacist'].includes(auth.user?.role) && p.status==='pending'" class="btn btn-sm btn-outline-danger" @click="review(p,'reject')">Reject</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="text-center text-muted py-4">No prescriptions uploaded.</td></tr></tbody></table></div></div></div></template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import api from '../api';import {Swal} from '../utils/swal';import {useAuth} from '../stores/auth';const auth=useAuth();const rows=ref([]),medicines=ref([]),show=ref(false),form=reactive({customer_id:'',doctor_name:'',doctor_license:'',prescription_date:new Date().toISOString().slice(0,10),notes:'',file:null,medicine_id:'',quantity:1,instructions:''});async function load(){rows.value=(await api.get('/prescriptions')).data.data||[];}async function create(){const fd=new FormData();Object.entries(form).forEach(([k,v])=>{if(v!==null&&v!==''&&!['medicine_id','quantity','instructions'].includes(k))fd.append(k,v)});if(form.medicine_id){fd.append('items[0][medicine_id]',form.medicine_id);fd.append('items[0][quantity]',form.quantity);fd.append('items[0][instructions]',form.instructions)};await api.post('/prescriptions',fd,{headers:{'Content-Type':'multipart/form-data'}});show.value=false;await load();}async function openFile(p){const {data}=await api.get(`/prescriptions/${p.id}/file`,{responseType:'blob'});const url=URL.createObjectURL(data);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}async function review(p,decision){const r=await Swal.fire({title:`${decision} prescription?`,input:'text',inputLabel:'Optional note',showCancelButton:true});if(!r.isConfirmed)return;await api.post(`/prescriptions/${p.id}/review`,{decision,notes:r.value});await load();}onMounted(async()=>{await load();medicines.value=(await api.get('/medicines',{params:{per_page:100}})).data.data||[];});
</script>
